function confirmDelete(){var agree=confirm("Are you sure you want to delete this record?");if(agree)return!0;else return!1}
function fnSetDateFormat(oDateFormat){var sDateString;sDateString=oDateFormat.Date+"/"+oDateFormat.Month+"/"+oDateFormat.FullYear;return sDateString}
function setCookie(key,value){var expires=new Date();expires.setTime(expires.getTime()+1*24*60*60*1000);document.cookie=key+"="+value+";expires="+expires.toUTCString()}
function onCall(number){window.location.href="tel:+91-"+number}
function changeDisplayRowCount(numRecords){displayRecords(numRecords,1)}
function displayRecords(numRecords,pageNum){var filterstr="";if($("#listfilterproptype").length){var listfilterproptype=$("#listfilterproptype").val()}else{var listfilterproptype=0}
var mobileSearch=$("#filteredMobileCardSearch").length?$("#filteredMobileCardSearch").val():"";var mobileOrderBy=$("#filteredMobileSort").length?$("#filteredMobileSort").val():"";if(mobileSearch){filterstr+="&mobilesearch="+encodeURIComponent(mobileSearch)}
if(mobileOrderBy){filterstr+="&mobileorderby="+encodeURIComponent(mobileOrderBy)}
$.ajax({type:"POST",url:"ajaxpaginationlist.php",data:"show="+numRecords+"&pagenum="+pageNum+"&propertytype="+listfilterproptype+filterstr,cache:!1,beforeSend:function(){$(".loader").html('<img src="assets/ajax-loader.gif" alt="" width="24" height="24" >',)},success:function(html){$("#results").html(html);$(".loader").html("");$("[data-toggle^=popover_desc]").popover();var $mobileTotal=$("#results #mobileListingTotal");var $totalSlot=$("#filteredMobileResultsTotal");if($totalSlot.length){if($mobileTotal.length){var totalRecords=parseInt($mobileTotal.attr("data-total"),10)||0;$totalSlot.text(totalRecords.toLocaleString("en-IN")+(totalRecords===1?" record":" records"),).prop("hidden",!1)}else{$totalSlot.prop("hidden",!0)}}
setTimeout(function(){var tableWidth=$("#tblpropertylisting").outerWidth();if(tableWidth>0){$(".footer-desktop, .footer-mobile").css("width",tableWidth+"px")}},100);$("html, body").animate({scrollTop:0},"slow")},})}
function Disable_Control_C(){var keystroke=String.fromCharCode(event.keyCode).toLowerCase();if(event.ctrlKey&&(keystroke=="c"||keystroke=="v")){alert("Copy is not allowed");event.returnValue=!1}}
function getformatedvalue(amount){if(/\D/g.test(amount)){this.value=amount.replace(/\D/g,"")}
if($.isNumeric(amount)){if(amount>=10000000)amount=amount/10000000+" Cr";else if(amount>=100000)amount=amount/100000+" Lac";else if(amount>=1000)amount=amount/1000+" Th";return amount}else{return!1}}
function triggerImageGallery(propertyId){$("#imageGalleryModal").remove();$(document).off("keydown.imageGallery");var modalHtml=`
        <div class="modal fade" id="imageGalleryModal" tabindex="-1" role="dialog" aria-labelledby="imageGalleryModalLabel" aria-hidden="true">
          <div class="modal-dialog modal-gallery-responsive" role="document">
            <div class="modal-content modal-gallery-content">
              <div class="modal-header modal-gallery-header">
                <div class="modal-gallery-header-content">
                  <span class="modal-gallery-icon" aria-hidden="true"><i class="fa-regular fa-images"></i></span>
                  <div class="modal-gallery-title-group">
                    <h5 class="modal-title" id="imageGalleryModalLabel">Property photos</h5>
                    <span class="modal-gallery-subtitle">Use arrows, thumbnails, or swipe</span>
                  </div>
                  <button type="button" class="close modal-gallery-close" data-dismiss="modal" aria-label="Close">
                    <i class="fa-solid fa-xmark" aria-hidden="true"></i>
                  </button>
                </div>
              </div>
              <div class="modal-body modal-gallery-body" id="galleryImages">
                <div class="modal-gallery-loading"><span class="modal-gallery-spinner"></span> Loading photos...</div>
              </div>
            </div>
          </div>
        </div>
    `;$("body").append(modalHtml);$("#imageGalleryModal").modal("show");$.ajax({type:"POST",url:"ajaxgetimages.php",data:{propertyId:propertyId,ajax:!0},success:function(data){$("#galleryImages").html(data);initImageGallery($("#galleryImages"))},error:function(){$("#galleryImages").html('<div class="tp-gallery-empty tp-gallery-empty--error">Failed to load photos.</div>',)},})}
function initImageGallery($root){var $gallery=$root.find("[data-gallery]").first();if(!$gallery.length)return;var images=[];try{images=JSON.parse($gallery.find(".js-gallery-images").first().text()||"[]",)}catch(e){images=[]}
if(!images.length)return;var index=0;var $image=$gallery.find(".tp-gallery__image");var $current=$gallery.find("[data-gallery-current]");var $thumbs=$gallery.find("[data-gallery-thumb]");var touchStartX=null;function preload(nextIndex){if(!images[nextIndex])return;var img=new Image();img.src=images[nextIndex]}
function show(nextIndex){index=(nextIndex+images.length)%images.length;$gallery.addClass("is-loading-image");$image.attr("src",images[index]).attr("alt","Property photo "+(index+1));$current.text(index+1);$thumbs.removeClass("is-active").attr("aria-selected","false").filter('[data-gallery-thumb="'+index+'"]').addClass("is-active").attr("aria-selected","true");preload((index+1)%images.length)}
if(images.length<2){$gallery.addClass("is-single")}
$image.on("load",function(){$gallery.removeClass("is-loading-image")});$gallery.on("click","[data-gallery-prev]",function(e){e.preventDefault();show(index-1)});$gallery.on("click","[data-gallery-next]",function(e){e.preventDefault();show(index+1)});$gallery.on("click","[data-gallery-thumb]",function(e){e.preventDefault();show(parseInt($(this).attr("data-gallery-thumb"),10)||0)});$gallery.on("touchstart",".tp-gallery__stage",function(e){touchStartX=e.originalEvent.changedTouches[0].screenX});$gallery.on("touchend",".tp-gallery__stage",function(e){if(touchStartX===null)return;var dx=e.originalEvent.changedTouches[0].screenX-touchStartX;if(Math.abs(dx)>42){show(dx>0?index-1:index+1)}
touchStartX=null});$(document).off("keydown.imageGallery").on("keydown.imageGallery",function(e){if(!$("#imageGalleryModal").is(":visible"))return;if(e.key==="ArrowLeft"){e.preventDefault();show(index-1)}else if(e.key==="ArrowRight"){e.preventDefault();show(index+1)}else if(e.key==="Escape"){$("#imageGalleryModal").modal("hide")}});$("#imageGalleryModal").off("click.imageGalleryCleanup").on("click.imageGalleryCleanup",function(e){if(e.target===this){$("#imageGalleryModal").modal("hide");$(document).off("keydown.imageGallery");return}
if($(e.target).closest("[data-dismiss='modal']").length){$(document).off("keydown.imageGallery")}}).off("hidden.bs.modal.imageGallery").on("hidden.bs.modal.imageGallery",function(){$(document).off("keydown.imageGallery")});preload(1)}
